function renderSavedBar(){const bar=$('#savedBar');if(!bar)return;bar.innerHTML=`<button data-saved-view="favorites" aria-label="Избранное">★ Избр. <b>${data.filter(d=>d.favorite).length}</b></button><button data-saved-view="repeat" aria-label="Повторить слова">↻ Повтор <b>${data.filter(d=>d.state==='Повторить').length}</b></button><button id="floatingSections" aria-label="Открыть разделы" aria-expanded="false" aria-controls="floatingSectionsMenu" title="Разделы">☰</button><button id="floatingSearch" aria-label="Поиск по всей базе" title="Поиск по всей базе">⌕</button>`;bar.querySelector('#floatingSearch').onclick=openGlobalSearch;bar.querySelector('#floatingSections').onclick=toggleFloatingSections;bar.querySelectorAll('[data-saved-view]').forEach(b=>b.onclick=()=>nav(b.dataset.savedView));document.querySelectorAll('[data-list-count]').forEach(el=>el.textContent=data.filter(d=>el.dataset.listCount==='repeat'?d.state==='Повторить':d.favorite).length)}
function bind(){if($('#shuffleCards'))$('#shuffleCards').onclick=()=>{const items=shuffled(filtered());shuffledOrders.set(view,new Map(items.map((d,i)=>[d.id,i])));page=0;render()};if($('#shuffleLessons'))$('#shuffleLessons').onclick=()=>{const items=shuffled((corpus.lessons||[]).filter(x=>lessonCategory==='Все'||x.category===lessonCategory));shuffledOrders.set('lessons',new Map(items.map((x,i)=>[x.category+'\u0000'+x.title,i])));render()};if($('#reviewBack'))$('#reviewBack').onclick=()=>{if(reviewAt>0){reviewAt--;render()}};if($('#reviewForward'))$('#reviewForward').onclick=()=>{if(reviewAt<reviewQueue.length){reviewAt++;render()}};if($('#lessonVocabulary'))$('#lessonVocabulary').onclick=()=>{nav('base');sourceFilter='Уроки 燕子';render()};document.querySelectorAll('[data-memorized]').forEach(b=>b.onclick=()=>{const d=data.find(x=>x.id===b.dataset.memorized);if(!d)return;update({...d,state:'Изучено',viewedAt:d.viewedAt||Date.now(),memoryAt:Date.now(),due:Date.now()+3*86400000});render();toast('Отмечено «Помню»')});if($('#undoRemember'))$('#undoRemember').onclick=()=>{const d=data.find(d=>d.id===reviewQueue[reviewAt]);if(!d)return;update({...d,state:'Повторить',memoryAt:Date.now(),due:Date.now()+60000});render()};for(const id of ['quizGroup','quizTopic'])if($('#'+id))$('#'+id).onchange=e=>{if(id==='quizGroup'){quizMode=e.target.value;quizTopic=''}else quizTopic=e.target.value;quiz=[];quizStarted=false;render()};document.querySelectorAll('[data-star]').forEach(b=>b.onclick=()=>toggleFavorite(b.dataset.star));if($('#reloadSources'))$('#reloadSources').onclick=loadSources;document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>nav(b.dataset.go));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit));document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{const category=b.dataset.category;if(selectedTopics.has(category))selectedTopics.delete(category);else selectedTopics.add(category);topic='';if(!['base','tech','repeat','favorites'].includes(view))view='tech';page=0;reviewQueue=[];render();window.scrollTo(0,0)});if($('#add'))$('#add').onclick=()=>edit();for(const k of ['topic','level','status','sourceFilter','quality'])if($('#'+k))$('#'+k).onchange=e=>{const v=e.target.value;if(k==='topic'){topic=v;selectedTopics.clear();}if(k==='level')level=v;if(k==='status')status=v;if(k==='sourceFilter')sourceFilter=v;if(k==='quality')quality=v;filterChanged()};if($('#onlyWork'))$('#onlyWork').onchange=e=>{onlyWork=e.target.checked;filterChanged()};if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;filterChanged();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#reset'))$('#reset').onclick=()=>{resetFilters();render()};if($('#prev'))$('#prev').onclick=()=>{page--;render();window.scrollTo(0,0)};if($('#more'))$('#more').onclick=()=>{page++;render();window.scrollTo(0,0)};if($('#practiceFiltered'))$('#practiceFiltered').onclick=()=>{const ids=shuffled(filtered().filter(reviewEligible)).map(d=>d.id);if(!ids.length){toast('В этой подборке пока нет слов.');return}if(view==='tech')onlyWork=true;view='cards';reviewQueue=ids;reviewAt=reviewDone=0;revealed=false;render()};if($('#testFiltered'))$('#testFiltered').onclick=()=>{const pool=filtered();if(pool.filter(d=>d.complete).length<4){toast('Нужно не менее 4 полных записей в выборке.');return}quizMode='Выборка';quizTopic='';quizSelection=pool.map(d=>d.id);startQuiz(pool);view='quiz';render()};document.querySelectorAll('[data-memory]').forEach(b=>b.onclick=()=>{if(revealed)return;const d=data.find(d=>d.id===reviewQueue[reviewAt]);update({...d,viewedAt:d.viewedAt||Date.now(),memoryAt:Date.now(),state:b.dataset.memory==='know'?'Изучено':'Повторить',due:Date.now()+(b.dataset.memory==='know'?3*86400000:60000)});reviewAnswered.add(reviewAt);revealed=true;reviewDone=reviewAnswered.size;render()});if($('#nextCard'))$('#nextCard').onclick=()=>{reviewAt++;revealed=false;render()};if($('#reveal'))$('#reveal').onclick=()=>{revealed=true;render()};document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{const d=data.find(d=>d.id===reviewQueue[reviewAt]);if(!d)return;const action=b.dataset.rate;update({...d,state:action==='know'?'Изучено':'Повторить',due:Date.now()+(action==='know'?3*86400000:action==='tomorrow'?86400000:60000)});if(action==='again')reviewQueue.push(d.id);reviewAt++;reviewDone++;revealed=false;render()});if($('#reviewAll'))$('#reviewAll').onclick=()=>{reviewQueue=shuffled(filtered().filter(reviewEligible)).map(d=>d.id);reviewAt=reviewDone=0;revealed=false;render()};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{quizMode=b.dataset.mode;quizTopic='';quizStarted=false;quiz=[];render()});for(const id of ['newQuiz','newQuizBottom'])if($('#'+id))$('#'+id).onclick=()=>{startQuiz(quizPool());render()};document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(+b.dataset.answer));document.querySelectorAll('[data-process]').forEach(b=>b.onclick=()=>edit(null,raw.find(r=>r.id===b.dataset.process)));document.querySelectorAll('[data-mark]').forEach(b=>b.onclick=()=>{const id=b.dataset.mark;completed=completed.includes(id)?completed.filter(x=>x!==id):[...completed,id];persist();render()});document.querySelectorAll('[data-related]').forEach(b=>b.onclick=()=>{const r=raw.find(x=>x.id===b.dataset.related),found=data.filter(d=>d.sources.some(s=>s.sheet===r.source&&s.row===r.row));if(!found.length){toast('Строка ещё не преобразована в словарь. Создай запись вручную.');return}showRelated(r,found)});if($('#export'))$('#export').onclick=exportJSON;if($('#exportCSV'))$('#exportCSV').onclick=exportCSV;if($('#upload')){$('#upload').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const f=e.target.files[0];if(f)await importFile(f)};$('#parse').onclick=()=>ingest($('#paste').value,'Вставка из таблицы')}}
function answer(i){if(answered)return;answered=true;const q=quiz[quizAt],ok=q.options[i].id===q.d.id;if(ok)score++;else{wrong.push(q.d);update({...q.d,state:'Повторить',due:Date.now()})}history.push({time:Date.now(),id:q.d.id,ok,mode:quizMode});persist();document.querySelectorAll('[data-answer]').forEach((b,j)=>{b.disabled=true;if(q.options[j].id===q.d.id)b.classList.add('good');else if(j===i)b.classList.add('wrong')});$('#feedback').innerHTML=`<div class="${ok?'ok':'bad'}">${ok?'Верно':'Правильный ответ'}<div class="zh">${esc(q.d.zh)}</div><div class="py">${esc(q.d.py)}</div><div>${esc(q.d.ru)}</div>${examplesHTML(q.d)}${q.d.pyOrigin==='Автоматически'?'<small>Пиньинь сформирован автоматически.</small>':''}</div><p><button id="next" class="primary">${quizAt+1===quiz.length?'Результат':'Следующий вопрос'} →</button></p>`;$('#next').onclick=()=>{quizAt++;answered=false;render()}}
function showRelated(r,found){let dlg=document.createElement('dialog');dlg.innerHTML=`<h2>${esc(r.source)} · строка ${r.row}</h2><p>Найдено записей: ${found.length}</p>${found.map(d=>`<div class="source-cell"><div class="zh">${esc(d.zh)}</div><div class="py">${esc(d.py)}</div>${esc(d.ru)||'Нужен перевод'}</div>`).join('')}<p><button>Закрыть</button></p>`;document.body.append(dlg);dlg.querySelector('button').onclick=()=>dlg.close();dlg.onclose=()=>dlg.remove();dlg.showModal()}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function exportJSON(){if(!corpus.raw?.length)await loadSources();download('my-chinese-full-backup.json',JSON.stringify({version:2,exported:new Date().toISOString(),data:data.map(({_search,...d})=>d),raw,completed,history,sheets,writing:Object.fromEntries(writingRecords),deleted,sourceUrl:corpus.sourceUrl}), 'application/json');toast('Экспорт подготовлен. Сохрани файл как резервную копию.')}
function exportCSV(){const keys=['zh','py','ru','topic','tags','level','work','source','ex','ep','er'];const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';download('my-chinese-dictionary.csv','\ufeff'+[keys,...data.map(d=>keys.map(k=>k==='tags'?d.tags.join(', '):d[k]))].map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const first=text.split('\n')[0],sep=first.includes('\t')?'\t':first.includes(';')?';':',';let rows=[],r=[],v='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++}else quoted=!quoted}else if(c===sep&&!quoted){r.push(v);v=''}else if(c==='\n'&&!quoted){r.push(v.replace(/\r$/,''));rows.push(r);r=[];v=''}else v+=c}if(quoted)throw Error('Незакрытые кавычки CSV');if(v||r.length){r.push(v);rows.push(r)}return rows}
function ingest(text,source){try{const rows=parseCSV(text),headers=(rows[0]||[]).map(x=>x.trim().toLowerCase()),known=headers.includes('zh');let n=0,dups=0;for(const [i,r]of rows.slice(known?1:0).entries()){if(!r.some(x=>x.trim()))continue;const candidate=known?Object.fromEntries(headers.map((h,j)=>[h,r[j]?.trim()||''])):{};if(candidate.zh&&candidate.ru&&candidate.py){if(data.some(d=>norm(d.zh)===norm(candidate.zh))){dups++;continue}candidate.id='user-'+uuid();candidate.tags=(candidate.tags||candidate.topic||'Общая лексика').split(',').map(s=>s.trim()).filter(Boolean);candidate.topic=candidate.topic||candidate.tags[0];candidate.work=candidate.work==='true'||candidate.tags.some(t=>WORK_TOPICS.includes(t));candidate.source=candidate.source||source;candidate.quality='Импортировано вручную';update(candidate)}else extraRaw.push({id:'import-'+uuid(),source,row:i+(known?2:1),text:r.join(' | '),candidate,cells:r.map((text,j)=>({col:j+1,text}))});n++}rebuild();persist();render();toast(`Добавлено: ${n}; повторов пропущено: ${dups}`)}catch(e){toast('Импорт не выполнен: '+e.message)}}
async function importFile(file){try{const text=await file.text();if(!file.name.toLowerCase().endsWith('.json')){ingest(text,file.name);return}const j=JSON.parse(text);if(!Array.isArray(j.data)||!j.data.every(d=>d&&typeof d.zh==='string'&&d.zh.trim()))throw Error('Нужен JSON-экспорт приложения с массивом data');let n=0;const by=new Map(data.map(d=>[norm(d.zh),d]));for(const incoming of j.data){const old=by.get(norm(incoming.zh));let d=standard({...old,...incoming,id:old?.id||incoming.id||'user-'+uuid()});if(old){d.tags=[...new Set([...old.tags,...d.tags])];d.sources=[...old.sources,...d.sources.filter(s=>!old.sources.some(x=>x.sheet===s.sheet&&x.row===s.row&&x.col===s.col))]}edits[d.id]=d;n++}const rawIds=new Set(raw.map(r=>r.id));if(Array.isArray(j.raw))for(const r of j.raw)if(typeof r.id==='string'&&typeof r.text==='string'&&!rawIds.has(r.id)){extraRaw.push(r);rawIds.add(r.id)}completed=[...new Set([...completed,...(Array.isArray(j.completed)?j.completed:[])])];history=[...history,...(Array.isArray(j.history)?j.history:[])];deleted=[...new Set([...deleted,...(Array.isArray(j.deleted)?j.deleted:[])])];await writingLoaded;writingApplyCloud(j.writing||{});rebuild();persist();render();toast('Записей восстановлено / объединено: '+n)}catch(e){toast('Импорт не выполнен: '+e.message)}}
$('#cancel').onclick=()=>$('#editor').close();$('#delete').onclick=()=>{if(!editing)return;if(confirm('Убрать материал из учебной базы? Исходная строка останется доступна.')){deleted.push(editing);delete edits[editing];rebuild();persist();$('#editor').close();render()}};
$('#form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));for(const k of Object.keys(values))if(typeof values[k]==='string')values[k]=values[k].trim();const err=$('#formerror');if(!values.zh||!values.py||!values.ru||!values.topic){err.textContent='Заполни иероглифы, пиньинь, перевод и основную тему.';return}if((values.ex||values.ep||values.er)&&!(values.ex&&values.ep&&values.er)){err.textContent='Для примера нужны иероглифы, пиньинь и перевод.';return}const duplicate=data.find(d=>d.id!==editing&&norm(d.zh)===norm(values.zh));if(duplicate){err.textContent='Это выражение уже есть: '+duplicate.ru+'. Найди его в базе и дополни существующую запись.';return}const old=data.find(d=>d.id===editing)||{};const tags=[...new Set([values.topic,...values.tags.split(',').map(t=>t.trim()).filter(Boolean)])];const d={...old,...values,id:editing||'user-'+uuid(),tags,work:e.target.elements.work.checked,complete:true,pyOrigin:'Проверено вручную',quality:'Проверено вручную',examples:values.ex?[{zh:values.ex,py:values.ep,ru:values.er,origin:'Добавлен вручную'},...(old.examples||[]).slice(1)]:[...(old.examples||[]).slice(1)],meanings:[values.ru,...(old.meanings||[]).filter(m=>m!==values.ru)]};if(rawId){const r=raw.find(r=>r.id===rawId);d.sources=[...(old.sources||[]),{sheet:r.source,row:r.row,col:1,url:corpus.sourceUrl}];if(!completed.includes(rawId))completed.push(rawId)}update(d);$('#editor').close();render();toast('Материал сохранён')};
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));
fetch('source.json').then(r=>{if(!r.ok)throw Error('Исходник не загрузился');return r.json()}).then(async j=>{const fromDB=await readDB();if(fromDB){saved=fromDB;edits=saved.edits||{};deleted=saved.deleted||[];completed=saved.completed||[];history=saved.history||[];extraRaw=saved.extraRaw||[]}corpus=j;if(!saved){let legacy;try{legacy=JSON.parse(localStorage.getItem('chinese-workbench-v1')||'null')}catch{}if(legacy){const map=new Map(j.clean.map(d=>[norm(d.zh),d]));for(const old of legacy.data||[]){const baseline=map.get(norm(old.zh));if(baseline){if(old.state!=='Новое'||old.due)edits[baseline.id]={...baseline,state:old.state,due:old.due};if(old.id?.startsWith('seed'))edits[baseline.id]={...baseline,examples:old.ex?[{zh:old.ex,py:old.ep,ru:old.er}]:baseline.examples,ex:old.ex,ep:old.ep,er:old.er}}else edits[old.id]=standard(old)}completed=legacy.completed||[];history=legacy.history||[];extraRaw=legacy.extraRaw||[]}}rebuild();ready=true;render();if(window.ChineseCloud){await writingLoaded;const synced=await window.ChineseCloud.start(payload());writingApplyCloud(synced.writing||{});edits=synced.edits||{};deleted=synced.deleted||[];completed=synced.completed||[];history=synced.history||[];extraRaw=synced.extraRaw||[]}rebuild();ready=true;persist();render()}).catch(e=>{$('#app').innerHTML='<h1>Не удалось загрузить базу</h1><p>Проверь подключение и обнови страницу. Сохранённые правки в браузере остаются на месте.</p>';console.error(e)});

window.applyCloudState=function(p){writingApplyCloud(p.writing||{});edits=p.edits||{};deleted=p.deleted||[];completed=p.completed||[];history=p.history||[];extraRaw=p.extraRaw||[];rebuild();const snapshot=structuredClone(payload());dbReady.then(db=>{if(db){const tx=db.transaction('settings','readwrite');tx.objectStore('settings').put(snapshot,'state')}else fallbackSave(snapshot)});if(ready&&view!=='quiz')render()};

const mobileMenu=document.querySelector('#mobileMenu');for(const id of ['mobileMore','topMenu'])document.querySelector('#'+id)?.addEventListener('click',()=>mobileMenu.showModal());document.querySelector('#closeMobile')?.addEventListener('click',()=>mobileMenu.close());document.querySelectorAll('[data-sync-now]').forEach(b=>b.addEventListener('click',()=>window.ChineseCloud?.sync()));

let globalPage=0;
function searchRank(d,q){const fields=[d.zh,d.py,d.ru,...(d.meanings||[])].map(x=>fold(String(x||'').trim()));if(fields.some(x=>x===q))return 0;if(fields.some(x=>x.startsWith(q)))return 1;if(fields.some(x=>x.includes(q)))return 2;if((d.examples||[]).some(e=>fold([e.zh,e.py,e.ru].join(' ')).includes(q)))return 4;return 3}
function rankedMatches(list,q){return q?list.map((d,i)=>({d,i,rank:searchRank(d,q)})).sort((a,b)=>a.rank-b.rank||a.i-b.i).map(x=>x.d):list}
function globalMatches(){const q=fold($('#globalSearchInput').value.trim());return q?rankedMatches(data.filter(d=>d._search.includes(q)),q):[]}
function renderGlobalSearch(){const matches=globalMatches(),box=$('#globalSearchResults'),q=$('#globalSearchInput').value.trim(),shown=matches.slice(globalPage*20,(globalPage+1)*20);$('#globalSearchCount').textContent=q?`Найдено: ${num(matches.length)} · поиск по всей базе`:`Вся база: ${num(data.length)} записей. Начни вводить слово.`;box.innerHTML=shown.map(d=>`<button class="search-result" data-global-open="${esc(d.id)}"><span class="zh">${esc(d.zh)}</span><span class="py">${esc(d.py)}</span><span>${esc(d.ru)}</span><small>${esc(d.topic)}</small></button>`).join('')+(q&&!matches.length?'<p>Ничего не найдено. Попробуй другой вариант или поиск без тонов.</p>':'')+(matches.length>20?`<div class="bar"><button id="globalPrev" ${globalPage===0?'disabled':''}>Назад</button><span>${globalPage+1} / ${Math.ceil(matches.length/20)}</span><button id="globalNext" ${(globalPage+1)*20>=matches.length?'disabled':''}>Дальше</button></div>`:'');box.querySelectorAll('[data-global-open]').forEach(b=>b.onclick=()=>{const d=data.find(d=>d.id===b.dataset.globalOpen);markViewed(d.id);box.innerHTML=`<button id="globalBack">← К результатам поиска</button>${cardHTML(d)}`;$('#globalBack').onclick=renderGlobalSearch;box.querySelector('[data-edit]').onclick=()=>{$('#globalSearchDialog').close();edit(d.id)};box.querySelector('[data-star]').onclick=()=>{toggleFavorite(d.id);const current=data.find(x=>x.id===d.id),star=box.querySelector('[data-star]');star.classList.toggle('starred',!!current.favorite);star.setAttribute('aria-checked',String(!!current.favorite));star.setAttribute('aria-label',current.favorite?'Убрать из избранного':'Добавить в избранное');star.innerHTML=current.favorite?'★':'☆'};box.querySelectorAll('[data-category]').forEach(t=>t.onclick=()=>{$('#globalSearchDialog').close();resetFilters();topic=t.dataset.category;view='base';render()})});if($('#globalPrev'))$('#globalPrev').onclick=()=>{globalPage--;renderGlobalSearch()};if($('#globalNext'))$('#globalNext').onclick=()=>{globalPage++;renderGlobalSearch()}}
function openGlobalSearch(){if(!ready)return;globalPage=0;$('#globalSearchDialog').showModal();renderGlobalSearch();$('#globalSearchInput').focus({preventScroll:true})}
$('#globalSearchButton').onclick=openGlobalSearch;$('#closeGlobalSearch').onclick=()=>$('#globalSearchDialog').close();$('#globalSearchInput').oninput=()=>{globalPage=0;renderGlobalSearch()};document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openGlobalSearch()}});

let wordObserver=null,viewTimers=new Map();
function markViewed(id){const d=data.find(x=>x.id===id);if(!d||d.viewedAt)return;update({...d,viewedAt:Date.now()})}
function observeWords(){
 wordObserver?.disconnect();for(const timer of viewTimers.values())clearTimeout(timer);viewTimers.clear();
 if(typeof IntersectionObserver==='undefined')return;
 wordObserver=new IntersectionObserver(entries=>{for(const e of entries){const id=e.target.dataset.wordId;if(e.isIntersecting&&document.visibilityState==='visible'){if(!viewTimers.has(id))viewTimers.set(id,setTimeout(()=>{if(document.visibilityState==='visible')markViewed(id);viewTimers.delete(id)},650))}else{clearTimeout(viewTimers.get(id));viewTimers.delete(id)}}},{threshold:0.35});
 document.querySelectorAll('#app [data-word-id]').forEach(el=>wordObserver.observe(el));
}
function dashboardStats(){const remembered=data.filter(d=>d.state==='Изучено').length,seen=data.filter(d=>d.viewedAt||d.state==='Изучено'||d.state==='Повторить').length;return {remembered,seen,repeat:data.filter(d=>d.state==='Повторить').length,total:data.length}}
function dashboardHTML(){const s=dashboardStats(),pct=s.total?Math.round(s.remembered/s.total*1000)/10:0,day=new Date().toLocaleDateString('sv-SE'),today=data.filter(d=>d.viewedAt&&new Date(d.viewedAt).toLocaleDateString('sv-SE')===day).length;
const topics=WORK_TOPICS.map(t=>{const a=data.filter(d=>d.tags.includes(t));return {t,total:a.length,seen:a.filter(d=>d.viewedAt||d.state!=='Новое').length,known:a.filter(d=>d.state==='Изучено').length}}).filter(x=>x.total);
return `<h1>Мой прогресс</h1><p class="sub">Каждая карточка считается один раз. Отметки сохраняются в аккаунте при доступной синхронизации.</p><div class="stats progress-stats"><div class="stat">Просмотрено<b>${num(s.seen)}</b><small>из ${num(s.total)} уникальных карточек</small></div><div class="stat">Помню<b>${num(s.remembered)}</b><small>текущая отметка «Помню»</small></div><div class="stat">Нужно повторить<b>${num(s.repeat)}</b><small>отметка «Не помню» и ошибки в тестах</small></div><div class="stat">Новых просмотрено сегодня<b>${num(today)}</b><small>первые просмотры за день</small></div></div><section class="panel" style="margin-top:20px"><h2>Помню ${pct}% базы</h2><progress aria-label="Доля слов с отметкой Помню" max="${s.total||1}" value="${s.remembered}"></progress><p class="sub">Без отметки «Помню»: ${num(s.total-s.remembered)}. В базе есть слова, фразы и конструкции.</p><div class="bar"><button data-go="cards" class="primary">Продолжить карточки →</button><button data-go="repeat">Разобрать повторение</button><button data-go="quiz">Тест по теме</button></div></section><p class="notice">Просмотр записывается, когда карточка видна на экране. Учёт просмотров начат 10 ноября 2026; прежние «Помню» и «Повторить» тоже учтены как просмотренные. Повторное открытие не увеличивает число. «Не помню» снимает отметку «Помню».</p><h2>Прогресс по рабочим темам</h2><div class="scrolltable"><table><thead><tr><th>Тема</th><th>Просмотрено</th><th>Помню</th><th>Всего</th></tr></thead><tbody>${topics.map(x=>`<tr><td>${esc(x.t)}</td><td>${num(x.seen)}</td><td>${num(x.known)}</td><td>${num(x.total)}</td></tr>`).join('')}</tbody></table></div><p class="sub">Одно слово может входить в несколько тем; строки таблицы не суммируются.</p><h2>Наполнение примерами</h2><p>${num(data.filter(d=>d.examples.length).length)} карточек с примерами из ${num(s.total)}.</p>`}

let lessonCategory='Все';
function lessonsHTML(){const categories=['Все',...new Set((corpus.lessons||[]).map(x=>x.category))];setTimeout(()=>document.querySelectorAll('[data-lesson-category]').forEach(b=>b.onclick=()=>{lessonCategory=b.dataset.lessonCategory;render()}),0);return `<h1>УРОКИ</h1><p class="sub">${(corpus.lessons||[]).length} разборов из записей Яньцзы: объяснения и примеры для повторения. Учебные примеры отредактированы; полный оригинал сохранён в источниках.</p><div class="topic-strip">${categories.map(c=>`<button data-lesson-category="${esc(c)}" class="${c===lessonCategory?'active':''}">${esc(c)}</button>`).join('')}</div><div class="bar"><button id="shuffleLessons">⤨ Перемешать</button><button id="lessonVocabulary">Словарь уроков</button><a href="${esc(corpus.lessonImport?.sourceUrl)}" target="_blank" rel="noopener">Открыть записи уроков</a></div><div class="grid">${shuffledViewItems((corpus.lessons||[]).filter(x=>lessonCategory==='Все'||x.category===lessonCategory),'lessons',x=>x.category+'\u0000'+x.title).map(x=>`<article class="item"><span class="tag">${esc(x.category)}</span><h2>${esc(x.title)}</h2><div class="zh">${esc(x.pattern)}</div><div class="py">${esc(x.patternPy)}</div><p>${esc(x.explanation)}</p>${exampleHTML(x)}</article>`).join('')}</div>`}

